use split_decls_genesis :: ourprelude :: * ; #[rustc_doc_primitive = "bool"] #[doc (alias = "true")] #[doc (alias = "false")] #[doc = " The boolean type."] #[doc = ""] #[doc = " The `bool` represents a value, which could only be either [`true`] or [`false`]. If you cast"] #[doc = " a `bool` into an integer, [`true`] will be 1 and [`false`] will be 0."] #[doc = ""] #[doc = " # Basic usage"] #[doc = ""] #[doc = " `bool` implements various traits, such as [`BitAnd`], [`BitOr`], [`Not`], etc.,"] #[doc = " which allow us to perform boolean operations using `&`, `|` and `!`."] #[doc = ""] #[doc = " [`if`] requires a `bool` value as its conditional. [`assert!`], which is an"] #[doc = " important macro in testing, checks whether an expression is [`true`] and panics"] #[doc = " if it isn't."] #[doc = ""] #[doc = " ```"] #[doc = " let bool_val = true & false | false;"] #[doc = " assert!(!bool_val);"] #[doc = " ```"] #[doc = ""] #[doc = " [`true`]: ../std/keyword.true.html"] #[doc = " [`false`]: ../std/keyword.false.html"] #[doc = " [`BitAnd`]: ops::BitAnd"] #[doc = " [`BitOr`]: ops::BitOr"] #[doc = " [`Not`]: ops::Not"] #[doc = " [`if`]: ../std/keyword.if.html"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " A trivial example of the usage of `bool`:"] #[doc = ""] #[doc = " ```"] #[doc = " let praise_the_borrow_checker = true;"] #[doc = ""] #[doc = " // using the `if` conditional"] #[doc = " if praise_the_borrow_checker {"] #[doc = "     println!(\"oh, yeah!\");"] #[doc = " } else {"] #[doc = "     println!(\"what?!!\");"] #[doc = " }"] #[doc = ""] #[doc = " // ... or, a match pattern"] #[doc = " match praise_the_borrow_checker {"] #[doc = "     true => println!(\"keep praising!\"),"] #[doc = "     false => println!(\"you should praise!\"),"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Also, since `bool` implements the [`Copy`] trait, we don't"] #[doc = " have to worry about the move semantics (just like the integer and float primitives)."] #[doc = ""] #[doc = " Now an example of `bool` cast to integer type:"] #[doc = ""] #[doc = " ```"] #[doc = " assert_eq!(true as i32, 1);"] #[doc = " assert_eq!(false as i32, 0);"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_bool { } #[rustc_doc_primitive = "never"] #[doc (alias = "!")] #[doc = " The `!` type, also called \"never\"."] #[doc = ""] #[doc = " `!` represents the type of computations which never resolve to any value at all. For example,"] #[doc = " the [`exit`] function `fn exit(code: i32) -> !` exits the process without ever returning, and"] #[doc = " so returns `!`."] #[doc = ""] #[doc = " `break`, `continue` and `return` expressions also have type `!`. For example we are allowed to"] #[doc = " write:"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(never_type)]"] #[doc = " # fn foo() -> u32 {"] #[doc = " let x: ! = {"] #[doc = "     return 123"] #[doc = " };"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " Although the `let` is pointless here, it illustrates the meaning of `!`. Since `x` is never"] #[doc = " assigned a value (because `return` returns from the entire function), `x` can be given type"] #[doc = " `!`. We could also replace `return 123` with a `panic!` or a never-ending `loop` and this code"] #[doc = " would still be valid."] #[doc = ""] #[doc = " A more realistic usage of `!` is in this code:"] #[doc = ""] #[doc = " ```"] #[doc = " # fn get_a_number() -> Option<u32> { None }"] #[doc = " # loop {"] #[doc = " let num: u32 = match get_a_number() {"] #[doc = "     Some(num) => num,"] #[doc = "     None => break,"] #[doc = " };"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " Both match arms must produce values of type [`u32`], but since `break` never produces a value"] #[doc = " at all we know it can never produce a value which isn't a [`u32`]. This illustrates another"] #[doc = " behavior of the `!` type - expressions with type `!` will coerce into any other type."] #[doc = ""] #[doc = " [`u32`]: prim@u32"] #[doc = " [`exit`]: ../std/process/fn.exit.html"] #[doc = ""] #[doc = " # `!` and generics"] #[doc = ""] #[doc = " ## Infallible errors"] #[doc = ""] #[doc = " The main place you'll see `!` used explicitly is in generic code. Consider the [`FromStr`]"] #[doc = " trait:"] #[doc = ""] #[doc = " ```"] #[doc = " trait FromStr: Sized {"] #[doc = "     type Err;"] #[doc = "     fn from_str(s: &str) -> Result<Self, Self::Err>;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " When implementing this trait for [`String`] we need to pick a type for [`Err`]. And since"] #[doc = " converting a string into a string will never result in an error, the appropriate type is `!`."] #[doc = " (Currently the type actually used is an enum with no variants, though this is only because `!`"] #[doc = " was added to Rust at a later date and it may change in the future.) With an [`Err`] type of"] #[doc = " `!`, if we have to call [`String::from_str`] for some reason the result will be a"] #[doc = " [`Result<String, !>`] which we can unpack like this:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str::FromStr;"] #[doc = " let Ok(s) = String::from_str(\"hello\");"] #[doc = " ```"] #[doc = ""] #[doc = " Since the [`Err`] variant contains a `!`, it can never occur. This means we can exhaustively"] #[doc = " match on [`Result<T, !>`] by just taking the [`Ok`] variant. This illustrates another behavior"] #[doc = " of `!` - it can be used to \"delete\" certain enum variants from generic types like `Result`."] #[doc = ""] #[doc = " ## Infinite loops"] #[doc = ""] #[doc = " While [`Result<T, !>`] is very useful for removing errors, `!` can also be used to remove"] #[doc = " successes as well. If we think of [`Result<T, !>`] as \"if this function returns, it has not"] #[doc = " errored,\" we get a very intuitive idea of [`Result<!, E>`] as well: if the function returns, it"] #[doc = " *has* errored."] #[doc = ""] #[doc = " For example, consider the case of a simple web server, which can be simplified to:"] #[doc = ""] #[doc = " ```ignore (hypothetical-example)"] #[doc = " loop {"] #[doc = "     let (client, request) = get_request().expect(\"disconnected\");"] #[doc = "     let response = request.process();"] #[doc = "     response.send(client);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Currently, this isn't ideal, because we simply panic whenever we fail to get a new connection."] #[doc = " Instead, we'd like to keep track of this error, like this:"] #[doc = ""] #[doc = " ```ignore (hypothetical-example)"] #[doc = " loop {"] #[doc = "     match get_request() {"] #[doc = "         Err(err) => break err,"] #[doc = "         Ok((client, request)) => {"] #[doc = "             let response = request.process();"] #[doc = "             response.send(client);"] #[doc = "         },"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Now, when the server disconnects, we exit the loop with an error instead of panicking. While it"] #[doc = " might be intuitive to simply return the error, we might want to wrap it in a [`Result<!, E>`]"] #[doc = " instead:"] #[doc = ""] #[doc = " ```ignore (hypothetical-example)"] #[doc = " fn server_loop() -> Result<!, ConnectionError> {"] #[doc = "     loop {"] #[doc = "         let (client, request) = get_request()?;"] #[doc = "         let response = request.process();"] #[doc = "         response.send(client);"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Now, we can use `?` instead of `match`, and the return type makes a lot more sense: if the loop"] #[doc = " ever stops, it means that an error occurred. We don't even have to wrap the loop in an `Ok`"] #[doc = " because `!` coerces to `Result<!, ConnectionError>` automatically."] #[doc = ""] #[doc = " [`String::from_str`]: str::FromStr::from_str"] #[doc = " [`String`]: ../std/string/struct.String.html"] #[doc = " [`FromStr`]: str::FromStr"] #[doc = ""] #[doc = " # `!` and traits"] #[doc = ""] #[doc = " When writing your own traits, `!` should have an `impl` whenever there is an obvious `impl`"] #[doc = " which doesn't `panic!`. The reason is that functions returning an `impl Trait` where `!`"] #[doc = " does not have an `impl` of `Trait` cannot diverge as their only possible code path. In other"] #[doc = " words, they can't return `!` from every code path. As an example, this code doesn't compile:"] #[doc = ""] #[doc = " ```compile_fail"] #[doc = " use std::ops::Add;"] #[doc = ""] #[doc = " fn foo() -> impl Add<u32> {"] #[doc = "     unimplemented!()"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " But this code does:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::ops::Add;"] #[doc = ""] #[doc = " fn foo() -> impl Add<u32> {"] #[doc = "     if true {"] #[doc = "         unimplemented!()"] #[doc = "     } else {"] #[doc = "         0"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The reason is that, in the first example, there are many possible types that `!` could coerce"] #[doc = " to, because many types implement `Add<u32>`. However, in the second example,"] #[doc = " the `else` branch returns a `0`, which the compiler infers from the return type to be of type"] #[doc = " `u32`. Since `u32` is a concrete type, `!` can and will be coerced to it. See issue [#36375]"] #[doc = " for more information on this quirk of `!`."] #[doc = ""] #[doc = " [#36375]: https://github.com/rust-lang/rust/issues/36375"] #[doc = ""] #[doc = " As it turns out, though, most traits can have an `impl` for `!`. Take [`Debug`]"] #[doc = " for example:"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(never_type)]"] #[doc = " # use std::fmt;"] #[doc = " # trait Debug {"] #[doc = " #     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result;"] #[doc = " # }"] #[doc = " impl Debug for ! {"] #[doc = "     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {"] #[doc = "         *self"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Once again we're using `!`'s ability to coerce into any other type, in this case"] #[doc = " [`fmt::Result`]. Since this method takes a `&!` as an argument we know that it can never be"] #[doc = " called (because there is no value of type `!` for it to be called with). Writing `*self`"] #[doc = " essentially tells the compiler \"We know that this code can never be run, so just treat the"] #[doc = " entire function body as having type [`fmt::Result`]\". This pattern can be used a lot when"] #[doc = " implementing traits for `!`. Generally, any trait which only has methods which take a `self`"] #[doc = " parameter should have such an impl."] #[doc = ""] #[doc = " On the other hand, one trait which would not be appropriate to implement is [`Default`]:"] #[doc = ""] #[doc = " ```"] #[doc = " trait Default {"] #[doc = "     fn default() -> Self;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Since `!` has no values, it has no default value either. It's true that we could write an"] #[doc = " `impl` for this which simply panics, but the same is true for any type (we could `impl"] #[doc = " Default` for (eg.) [`File`] by just making [`default()`] panic.)"] #[doc = ""] #[doc = " [`File`]: ../std/fs/struct.File.html"] #[doc = " [`Debug`]: fmt::Debug"] #[doc = " [`default()`]: Default::default"] #[doc = ""] #[doc = " # Never type fallback"] #[doc = ""] #[doc = " When the compiler sees a value of type `!` in a [coercion site], it implicitly inserts a"] #[doc = " coercion to allow the type checker to infer any type:"] #[doc = ""] #[doc = " ```rust,ignore (illustrative-and-has-placeholders)"] #[doc = " // this"] #[doc = " let x: u8 = panic!();"] #[doc = ""] #[doc = " // is (essentially) turned by the compiler into"] #[doc = " let x: u8 = absurd(panic!());"] #[doc = ""] #[doc = " // where absurd is a function with the following signature"] #[doc = " // (it's sound, because `!` always marks unreachable code):"] #[doc = " fn absurd<T>(_: !) -> T { ... }"] #[doc = " ```"] #[doc = ""] #[doc = " This can lead to compilation errors if the type cannot be inferred:"] #[doc = ""] #[doc = " ```compile_fail"] #[doc = " // this"] #[doc = " { panic!() };"] #[doc = ""] #[doc = " // gets turned into this"] #[doc = " { absurd(panic!()) }; // error: can't infer the type of `absurd`"] #[doc = " ```"] #[doc = ""] #[doc = " To prevent such errors, the compiler remembers where it inserted `absurd` calls, and"] #[doc = " if it can't infer the type, it uses the fallback type instead:"] #[doc = " ```rust, ignore"] #[doc = " type Fallback = /* An arbitrarily selected type! */;"] #[doc = " { absurd::<Fallback>(panic!()) }"] #[doc = " ```"] #[doc = ""] #[doc = " This is what is known as \"never type fallback\"."] #[doc = ""] #[doc = " Historically, the fallback type was [`()`], causing confusing behavior where `!` spontaneously"] #[doc = " coerced to `()`, even when it would not infer `()` without the fallback. The fallback was changed"] #[doc = " to `!` in the [2024 edition], and will be changed in all editions at a later date."] #[doc = ""] #[doc = " [coercion site]: <https://doc.rust-lang.org/reference/type-coercions.html#coercion-sites>"] #[doc = " [`()`]: prim@unit"] #[doc = " [2024 edition]: <https://doc.rust-lang.org/edition-guide/rust-2024/never-type-fallback.html>"] #[doc = ""] #[unstable (feature = "never_type" , issue = "35121")] mod prim_never { } #[doc (hidden)] impl ! { } #[rustc_doc_primitive = "char"] #[allow (rustdoc :: invalid_rust_codeblocks)] #[doc = " A character type."] #[doc = ""] #[doc = " The `char` type represents a single character. More specifically, since"] #[doc = " 'character' isn't a well-defined concept in Unicode, `char` is a '[Unicode"] #[doc = " scalar value]'."] #[doc = ""] #[doc = " This documentation describes a number of methods and trait implementations on the"] #[doc = " `char` type. For technical reasons, there is additional, separate"] #[doc = " documentation in [the `std::char` module](char/index.html) as well."] #[doc = ""] #[doc = " # Validity and Layout"] #[doc = ""] #[doc = " A `char` is a '[Unicode scalar value]', which is any '[Unicode code point]'"] #[doc = " other than a [surrogate code point]. This has a fixed numerical definition:"] #[doc = " code points are in the range 0 to 0x10FFFF, inclusive."] #[doc = " Surrogate code points, used by UTF-16, are in the range 0xD800 to 0xDFFF."] #[doc = ""] #[doc = " No `char` may be constructed, whether as a literal or at runtime, that is not a"] #[doc = " Unicode scalar value. Violating this rule causes undefined behavior."] #[doc = ""] #[doc = " ```compile_fail"] #[doc = " // Each of these is a compiler error"] #[doc = " ['\\u{D800}', '\\u{DFFF}', '\\u{110000}'];"] #[doc = " ```"] #[doc = ""] #[doc = " ```should_panic"] #[doc = " // Panics; from_u32 returns None."] #[doc = " char::from_u32(0xDE01).unwrap();"] #[doc = " ```"] #[doc = ""] #[doc = " ```no_run"] #[doc = " // Undefined behavior"] #[doc = " let _ = unsafe { char::from_u32_unchecked(0x110000) };"] #[doc = " ```"] #[doc = ""] #[doc = " Unicode scalar values are also the exact set of values that may be encoded in UTF-8. Because"] #[doc = " `char` values are Unicode scalar values and functions may assume [incoming `str` values are"] #[doc = " valid UTF-8](primitive.str.html#invariant), it is safe to store any `char` in a `str` or read"] #[doc = " any character from a `str` as a `char`."] #[doc = ""] #[doc = " The gap in valid `char` values is understood by the compiler, so in the"] #[doc = " below example the two ranges are understood to cover the whole range of"] #[doc = " possible `char` values and there is no error for a [non-exhaustive match]."] #[doc = ""] #[doc = " ```"] #[doc = " let c: char = 'a';"] #[doc = " match c {"] #[doc = "     '\\0' ..= '\\u{D7FF}' => false,"] #[doc = "     '\\u{E000}' ..= '\\u{10FFFF}' => true,"] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[doc = " All Unicode scalar values are valid `char` values, but not all of them represent a real"] #[doc = " character. Many Unicode scalar values are not currently assigned to a character, but may be in"] #[doc = " the future (\"reserved\"); some will never be a character (\"noncharacters\"); and some may be given"] #[doc = " different meanings by different users (\"private use\")."] #[doc = ""] #[doc = " `char` is guaranteed to have the same size, alignment, and function call ABI as `u32` on all"] #[doc = " platforms."] #[doc = " ```"] #[doc = " use std::alloc::Layout;"] #[doc = " assert_eq!(Layout::new::<char>(), Layout::new::<u32>());"] #[doc = " ```"] #[doc = ""] #[doc = " [Unicode code point]: https://www.unicode.org/glossary/#code_point"] #[doc = " [Unicode scalar value]: https://www.unicode.org/glossary/#unicode_scalar_value"] #[doc = " [non-exhaustive match]: ../book/ch06-02-match.html#matches-are-exhaustive"] #[doc = " [surrogate code point]: https://www.unicode.org/glossary/#surrogate_code_point"] #[doc = ""] #[doc = " # Representation"] #[doc = ""] #[doc = " `char` is always four bytes in size. This is a different representation than"] #[doc = " a given character would have as part of a [`String`]. For example:"] #[doc = ""] #[doc = " ```"] #[doc = " let v = vec!['h', 'e', 'l', 'l', 'o'];"] #[doc = ""] #[doc = " // five elements times four bytes for each element"] #[doc = " assert_eq!(20, v.len() * size_of::<char>());"] #[doc = ""] #[doc = " let s = String::from(\"hello\");"] #[doc = ""] #[doc = " // five elements times one byte per element"] #[doc = " assert_eq!(5, s.len() * size_of::<u8>());"] #[doc = " ```"] #[doc = ""] #[doc = " [`String`]: ../std/string/struct.String.html"] #[doc = ""] #[doc = " As always, remember that a human intuition for 'character' might not map to"] #[doc = " Unicode's definitions. For example, despite looking similar, the 'é'"] #[doc = " character is one Unicode code point while 'e\u{301}' is two Unicode code points:"] #[doc = ""] #[doc = " ```"] #[doc = " let mut chars = \"é\".chars();"] #[doc = " // U+00e9: 'latin small letter e with acute'"] #[doc = " assert_eq!(Some('\\u{00e9}'), chars.next());"] #[doc = " assert_eq!(None, chars.next());"] #[doc = ""] #[doc = " let mut chars = \"e\u{301}\".chars();"] #[doc = " // U+0065: 'latin small letter e'"] #[doc = " assert_eq!(Some('\\u{0065}'), chars.next());"] #[doc = " // U+0301: 'combining acute accent'"] #[doc = " assert_eq!(Some('\\u{0301}'), chars.next());"] #[doc = " assert_eq!(None, chars.next());"] #[doc = " ```"] #[doc = ""] #[doc = " This means that the contents of the first string above _will_ fit into a"] #[doc = " `char` while the contents of the second string _will not_. Trying to create"] #[doc = " a `char` literal with the contents of the second string gives an error:"] #[doc = ""] #[doc = " ```text"] #[doc = " error: character literal may only contain one codepoint: 'e\u{301}'"] #[doc = " let c = 'e\u{301}';"] #[doc = "         ^^^"] #[doc = " ```"] #[doc = ""] #[doc = " Another implication of the 4-byte fixed size of a `char` is that"] #[doc = " per-`char` processing can end up using a lot more memory:"] #[doc = ""] #[doc = " ```"] #[doc = " let s = String::from(\"love: ❤\u{fe0f}\");"] #[doc = " let v: Vec<char> = s.chars().collect();"] #[doc = ""] #[doc = " assert_eq!(12, size_of_val(&s[..]));"] #[doc = " assert_eq!(32, size_of_val(&v[..]));"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_char { } #[rustc_doc_primitive = "unit"] #[doc (alias = "(")] #[doc (alias = ")")] #[doc (alias = "()")] #[doc = " The `()` type, also called \"unit\"."] #[doc = ""] #[doc = " The `()` type has exactly one value `()`, and is used when there"] #[doc = " is no other meaningful value that could be returned. `()` is most"] #[doc = " commonly seen implicitly: functions without a `-> ...` implicitly"] #[doc = " have return type `()`, that is, these are equivalent:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn long() -> () {}"] #[doc = ""] #[doc = " fn short() {}"] #[doc = " ```"] #[doc = ""] #[doc = " The semicolon `;` can be used to discard the result of an"] #[doc = " expression at the end of a block, making the expression (and thus"] #[doc = " the block) evaluate to `()`. For example,"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn returns_i64() -> i64 {"] #[doc = "     1i64"] #[doc = " }"] #[doc = " fn returns_unit() {"] #[doc = "     1i64;"] #[doc = " }"] #[doc = ""] #[doc = " let is_i64 = {"] #[doc = "     returns_i64()"] #[doc = " };"] #[doc = " let is_unit = {"] #[doc = "     returns_i64();"] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_unit { } #[doc (hidden)] impl () { } #[rustc_doc_primitive = "pointer"] #[doc (alias = "ptr")] #[doc (alias = "*")] #[doc (alias = "*const")] #[doc (alias = "*mut")] #[doc = " Raw, unsafe pointers, `*const T`, and `*mut T`."] #[doc = ""] #[doc = " *[See also the `std::ptr` module](ptr).*"] #[doc = ""] #[doc = " Working with raw pointers in Rust is uncommon, typically limited to a few patterns. Raw pointers"] #[doc = " can be out-of-bounds, unaligned, or [`null`]. However, when loading from or storing to a raw"] #[doc = " pointer, it must be [valid] for the given access and aligned. When using a field expression,"] #[doc = " tuple index expression, or array/slice index expression on a raw pointer, it follows the rules"] #[doc = " of [in-bounds pointer arithmetic][`offset`]."] #[doc = ""] #[doc = " Storing through a raw pointer using `*ptr = data` calls `drop` on the old value, so"] #[doc = " [`write`] must be used if the type has drop glue and memory is not already"] #[doc = " initialized - otherwise `drop` would be called on the uninitialized memory."] #[doc = ""] #[doc = " Use the [`null`] and [`null_mut`] functions to create null pointers, and the"] #[doc = " [`is_null`] method of the `*const T` and `*mut T` types to check for null."] #[doc = " The `*const T` and `*mut T` types also define the [`offset`] method, for"] #[doc = " pointer math."] #[doc = ""] #[doc = " # Common ways to create raw pointers"] #[doc = ""] #[doc = " ## 1. Coerce a reference (`&T`) or mutable reference (`&mut T`)."] #[doc = ""] #[doc = " ```"] #[doc = " let my_num: i32 = 10;"] #[doc = " let my_num_ptr: *const i32 = &my_num;"] #[doc = " let mut my_speed: i32 = 88;"] #[doc = " let my_speed_ptr: *mut i32 = &mut my_speed;"] #[doc = " ```"] #[doc = ""] #[doc = " To get a pointer to a boxed value, dereference the box:"] #[doc = ""] #[doc = " ```"] #[doc = " let my_num: Box<i32> = Box::new(10);"] #[doc = " let my_num_ptr: *const i32 = &*my_num;"] #[doc = " let mut my_speed: Box<i32> = Box::new(88);"] #[doc = " let my_speed_ptr: *mut i32 = &mut *my_speed;"] #[doc = " ```"] #[doc = ""] #[doc = " This does not take ownership of the original allocation"] #[doc = " and requires no resource management later,"] #[doc = " but you must not use the pointer after its lifetime."] #[doc = ""] #[doc = " ## 2. Consume a box (`Box<T>`)."] #[doc = ""] #[doc = " The [`into_raw`] function consumes a box and returns"] #[doc = " the raw pointer. It doesn't destroy `T` or deallocate any memory."] #[doc = ""] #[doc = " ```"] #[doc = " let my_speed: Box<i32> = Box::new(88);"] #[doc = " let my_speed: *mut i32 = Box::into_raw(my_speed);"] #[doc = ""] #[doc = " // By taking ownership of the original `Box<T>` though"] #[doc = " // we are obligated to put it together later to be destroyed."] #[doc = " unsafe {"] #[doc = "     drop(Box::from_raw(my_speed));"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Note that here the call to [`drop`] is for clarity - it indicates"] #[doc = " that we are done with the given value and it should be destroyed."] #[doc = ""] #[doc = " ## 3. Create it using `&raw`"] #[doc = ""] #[doc = " Instead of coercing a reference to a raw pointer, you can use the raw borrow"] #[doc = " operators `&raw const` (for `*const T`) and `&raw mut` (for `*mut T`)."] #[doc = " These operators allow you to create raw pointers to fields to which you cannot"] #[doc = " create a reference (without causing undefined behavior), such as an"] #[doc = " unaligned field. This might be necessary if packed structs or uninitialized"] #[doc = " memory is involved."] #[doc = ""] #[doc = " ```"] #[doc = " #[derive(Debug, Default, Copy, Clone)]"] #[doc = " #[repr(C, packed)]"] #[doc = " struct S {"] #[doc = "     aligned: u8,"] #[doc = "     unaligned: u32,"] #[doc = " }"] #[doc = " let s = S::default();"] #[doc = " let p = &raw const s.unaligned; // not allowed with coercion"] #[doc = " ```"] #[doc = ""] #[doc = " ## 4. Get it from C."] #[doc = ""] #[doc = " ```"] #[doc = " # mod libc {"] #[doc = " # pub unsafe fn malloc(_size: usize) -> *mut core::ffi::c_void { core::ptr::NonNull::dangling().as_ptr() }"] #[doc = " # pub unsafe fn free(_ptr: *mut core::ffi::c_void) {}"] #[doc = " # }"] #[doc = " # #[cfg(any())]"] #[doc = " #[allow(unused_extern_crates)]"] #[doc = " extern crate libc;"] #[doc = ""] #[doc = " unsafe {"] #[doc = "     let my_num: *mut i32 = libc::malloc(size_of::<i32>()) as *mut i32;"] #[doc = "     if my_num.is_null() {"] #[doc = "         panic!(\"failed to allocate memory\");"] #[doc = "     }"] #[doc = "     libc::free(my_num as *mut core::ffi::c_void);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Usually you wouldn't literally use `malloc` and `free` from Rust,"] #[doc = " but C APIs hand out a lot of pointers generally, so are a common source"] #[doc = " of raw pointers in Rust."] #[doc = ""] #[doc = " [`null`]: ptr::null"] #[doc = " [`null_mut`]: ptr::null_mut"] #[doc = " [`is_null`]: pointer::is_null"] #[doc = " [`offset`]: pointer::offset"] #[doc = " [`into_raw`]: ../std/boxed/struct.Box.html#method.into_raw"] #[doc = " [`write`]: ptr::write"] #[doc = " [valid]: ptr#safety"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_pointer { } #[rustc_doc_primitive = "array"] #[doc (alias = "[]")] #[doc (alias = "[T;N]")] #[doc (alias = "[T; N]")] #[doc = " A fixed-size array, denoted `[T; N]`, for the element type, `T`, and the"] #[doc = " non-negative compile-time constant size, `N`."] #[doc = ""] #[doc = " There are two syntactic forms for creating an array:"] #[doc = ""] #[doc = " * A list with each element, i.e., `[x, y, z]`."] #[doc = " * A repeat expression `[expr; N]` where `N` is how many times to repeat `expr` in the array. `expr` must either be:"] #[doc = ""] #[doc = "   * A value of a type implementing the [`Copy`] trait"] #[doc = "   * A `const` value"] #[doc = ""] #[doc = " Note that `[expr; 0]` is allowed, and produces an empty array."] #[doc = " This will still evaluate `expr`, however, and immediately drop the resulting value, so"] #[doc = " be mindful of side effects."] #[doc = ""] #[doc = " Arrays of *any* size implement the following traits if the element type allows it:"] #[doc = ""] #[doc = " - [`Copy`]"] #[doc = " - [`Clone`]"] #[doc = " - [`Debug`]"] #[doc = " - [`IntoIterator`] (implemented for `[T; N]`, `&[T; N]` and `&mut [T; N]`)"] #[doc = " - [`PartialEq`], [`PartialOrd`], [`Eq`], [`Ord`]"] #[doc = " - [`Hash`]"] #[doc = " - [`AsRef`], [`AsMut`]"] #[doc = " - [`Borrow`], [`BorrowMut`]"] #[doc = ""] #[doc = " Arrays of sizes from 0 to 32 (inclusive) implement the [`Default`] trait"] #[doc = " if the element type allows it. As a stopgap, trait implementations are"] #[doc = " statically generated up to size 32."] #[doc = ""] #[doc = " Arrays of sizes from 1 to 12 (inclusive) implement [`From<Tuple>`], where `Tuple`"] #[doc = " is a homogeneous [prim@tuple] of appropriate length."] #[doc = ""] #[doc = " Arrays coerce to [slices (`[T]`)][slice], so a slice method may be called on"] #[doc = " an array. Indeed, this provides most of the API for working with arrays."] #[doc = ""] #[doc = " Slices have a dynamic size and do not coerce to arrays. Instead, use"] #[doc = " `slice.try_into().unwrap()` or `<ArrayType>::try_from(slice).unwrap()`."] #[doc = ""] #[doc = " Array's `try_from(slice)` implementations (and the corresponding `slice.try_into()`"] #[doc = " array implementations) succeed if the input slice length is the same as the result"] #[doc = " array length. They optimize especially well when the optimizer can easily determine"] #[doc = " the slice length, e.g. `<[u8; 4]>::try_from(&slice[4..8]).unwrap()`. Array implements"] #[doc = " [TryFrom](crate::convert::TryFrom) returning:"] #[doc = ""] #[doc = " - `[T; N]` copies from the slice's elements"] #[doc = " - `&[T; N]` references the original slice's elements"] #[doc = " - `&mut [T; N]` references the original slice's elements"] #[doc = ""] #[doc = " You can move elements out of an array with a [slice pattern]. If you want"] #[doc = " one element, see [`mem::replace`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " let mut array: [i32; 3] = [0; 3];"] #[doc = ""] #[doc = " array[1] = 1;"] #[doc = " array[2] = 2;"] #[doc = ""] #[doc = " assert_eq!([1, 2], &array[1..]);"] #[doc = ""] #[doc = " // This loop prints: 0 1 2"] #[doc = " for x in array {"] #[doc = "     print!(\"{x} \");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " You can also iterate over reference to the array's elements:"] #[doc = ""] #[doc = " ```"] #[doc = " let array: [i32; 3] = [0; 3];"] #[doc = ""] #[doc = " for x in &array { }"] #[doc = " ```"] #[doc = ""] #[doc = " You can use `<ArrayType>::try_from(slice)` or `slice.try_into()` to get an array from"] #[doc = " a slice:"] #[doc = ""] #[doc = " ```"] #[doc = " let bytes: [u8; 3] = [1, 0, 2];"] #[doc = " assert_eq!(1, u16::from_le_bytes(<[u8; 2]>::try_from(&bytes[0..2]).unwrap()));"] #[doc = " assert_eq!(512, u16::from_le_bytes(bytes[1..3].try_into().unwrap()));"] #[doc = " ```"] #[doc = ""] #[doc = " You can use a [slice pattern] to move elements out of an array:"] #[doc = ""] #[doc = " ```"] #[doc = " fn move_away(_: String) { /* Do interesting things. */ }"] #[doc = ""] #[doc = " let [john, roa] = [\"John\".to_string(), \"Roa\".to_string()];"] #[doc = " move_away(john);"] #[doc = " move_away(roa);"] #[doc = " ```"] #[doc = ""] #[doc = " Arrays can be created from homogeneous tuples of appropriate length:"] #[doc = ""] #[doc = " ```"] #[doc = " let tuple: (u32, u32, u32) = (1, 2, 3);"] #[doc = " let array: [u32; 3] = tuple.into();"] #[doc = " ```"] #[doc = ""] #[doc = " # Editions"] #[doc = ""] #[doc = " Prior to Rust 1.53, arrays did not implement [`IntoIterator`] by value, so the method call"] #[doc = " `array.into_iter()` auto-referenced into a [slice iterator](slice::iter). Right now, the old"] #[doc = " behavior is preserved in the 2015 and 2018 editions of Rust for compatibility, ignoring"] #[doc = " [`IntoIterator`] by value. In the future, the behavior on the 2015 and 2018 edition"] #[doc = " might be made consistent to the behavior of later editions."] #[doc = ""] #[doc = " ```rust,edition2018"] #[doc = " // Rust 2015 and 2018:"] #[doc = ""] #[doc = " # #![allow(array_into_iter)] // override our `deny(warnings)`"] #[doc = " let array: [i32; 3] = [0; 3];"] #[doc = ""] #[doc = " // This creates a slice iterator, producing references to each value."] #[doc = " for item in array.into_iter().enumerate() {"] #[doc = "     let (i, x): (usize, &i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // The `array_into_iter` lint suggests this change for future compatibility:"] #[doc = " for item in array.iter().enumerate() {"] #[doc = "     let (i, x): (usize, &i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // You can explicitly iterate an array by value using `IntoIterator::into_iter`"] #[doc = " for item in IntoIterator::into_iter(array).enumerate() {"] #[doc = "     let (i, x): (usize, i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Starting in the 2021 edition, `array.into_iter()` uses `IntoIterator` normally to iterate"] #[doc = " by value, and `iter()` should be used to iterate by reference like previous editions."] #[doc = ""] #[doc = " ```rust,edition2021"] #[doc = " // Rust 2021:"] #[doc = ""] #[doc = " let array: [i32; 3] = [0; 3];"] #[doc = ""] #[doc = " // This iterates by reference:"] #[doc = " for item in array.iter().enumerate() {"] #[doc = "     let (i, x): (usize, &i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // This iterates by value:"] #[doc = " for item in array.into_iter().enumerate() {"] #[doc = "     let (i, x): (usize, i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Future language versions might start treating the `array.into_iter()`"] #[doc = " syntax on editions 2015 and 2018 the same as on edition 2021. So code using"] #[doc = " those older editions should still be written with this change in mind, to"] #[doc = " prevent breakage in the future. The safest way to accomplish this is to"] #[doc = " avoid the `into_iter` syntax on those editions. If an edition update is not"] #[doc = " viable/desired, there are multiple alternatives:"] #[doc = " * use `iter`, equivalent to the old behavior, creating references"] #[doc = " * use [`IntoIterator::into_iter`], equivalent to the post-2021 behavior (Rust 1.53+)"] #[doc = " * replace `for ... in array.into_iter() {` with `for ... in array {`,"] #[doc = "   equivalent to the post-2021 behavior (Rust 1.53+)"] #[doc = ""] #[doc = " ```rust,edition2018"] #[doc = " // Rust 2015 and 2018:"] #[doc = ""] #[doc = " let array: [i32; 3] = [0; 3];"] #[doc = ""] #[doc = " // This iterates by reference:"] #[doc = " for item in array.iter() {"] #[doc = "     let x: &i32 = item;"] #[doc = "     println!(\"{x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // This iterates by value:"] #[doc = " for item in IntoIterator::into_iter(array) {"] #[doc = "     let x: i32 = item;"] #[doc = "     println!(\"{x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // This iterates by value:"] #[doc = " for item in array {"] #[doc = "     let x: i32 = item;"] #[doc = "     println!(\"{x}\");"] #[doc = " }"] #[doc = ""] #[doc = " // IntoIter can also start a chain."] #[doc = " // This iterates by value:"] #[doc = " for item in IntoIterator::into_iter(array).enumerate() {"] #[doc = "     let (i, x): (usize, i32) = item;"] #[doc = "     println!(\"array[{i}] = {x}\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [slice]: prim@slice"] #[doc = " [`Debug`]: fmt::Debug"] #[doc = " [`Hash`]: hash::Hash"] #[doc = " [`Borrow`]: borrow::Borrow"] #[doc = " [`BorrowMut`]: borrow::BorrowMut"] #[doc = " [slice pattern]: ../reference/patterns.html#slice-patterns"] #[doc = " [`From<Tuple>`]: convert::From"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_array { } #[rustc_doc_primitive = "slice"] #[doc (alias = "[")] #[doc (alias = "]")] #[doc (alias = "[]")] #[doc = " A dynamically-sized view into a contiguous sequence, `[T]`."] #[doc = ""] #[doc = " Contiguous here means that elements are laid out so that every element is the same"] #[doc = " distance from its neighbors."] #[doc = ""] #[doc = " *[See also the `std::slice` module](crate::slice).*"] #[doc = ""] #[doc = " Slices are a view into a block of memory represented as a pointer and a"] #[doc = " length."] #[doc = ""] #[doc = " ```"] #[doc = " // slicing a Vec"] #[doc = " let vec = vec![1, 2, 3];"] #[doc = " let int_slice = &vec[..];"] #[doc = " // coercing an array to a slice"] #[doc = " let str_slice: &[&str] = &[\"one\", \"two\", \"three\"];"] #[doc = " ```"] #[doc = ""] #[doc = " Slices are either mutable or shared. The shared slice type is `&[T]`,"] #[doc = " while the mutable slice type is `&mut [T]`, where `T` represents the element"] #[doc = " type. For example, you can mutate the block of memory that a mutable slice"] #[doc = " points to:"] #[doc = ""] #[doc = " ```"] #[doc = " let mut x = [1, 2, 3];"] #[doc = " let x = &mut x[..]; // Take a full slice of `x`."] #[doc = " x[1] = 7;"] #[doc = " assert_eq!(x, &[1, 7, 3]);"] #[doc = " ```"] #[doc = ""] #[doc = " It is possible to slice empty subranges of slices by using empty ranges (including `slice.len()..slice.len()`):"] #[doc = " ```"] #[doc = " let x = [1, 2, 3];"] #[doc = " let empty = &x[0..0];   // subslice before the first element"] #[doc = " assert_eq!(empty, &[]);"] #[doc = " let empty = &x[..0];    // same as &x[0..0]"] #[doc = " assert_eq!(empty, &[]);"] #[doc = " let empty = &x[1..1];   // empty subslice in the middle"] #[doc = " assert_eq!(empty, &[]);"] #[doc = " let empty = &x[3..3];   // subslice after the last element"] #[doc = " assert_eq!(empty, &[]);"] #[doc = " let empty = &x[3..];    // same as &x[3..3]"] #[doc = " assert_eq!(empty, &[]);"] #[doc = " ```"] #[doc = ""] #[doc = " It is not allowed to use subranges that start with lower bound bigger than `slice.len()`:"] #[doc = " ```should_panic"] #[doc = " let x = vec![1, 2, 3];"] #[doc = " let _ = &x[4..4];"] #[doc = " ```"] #[doc = ""] #[doc = " As slices store the length of the sequence they refer to, they have twice"] #[doc = " the size of pointers to [`Sized`](marker/trait.Sized.html) types."] #[doc = " Also see the reference on"] #[doc = " [dynamically sized types](../reference/dynamically-sized-types.html)."] #[doc = ""] #[doc = " ```"] #[doc = " # use std::rc::Rc;"] #[doc = " let pointer_size = size_of::<&u8>();"] #[doc = " assert_eq!(2 * pointer_size, size_of::<&[u8]>());"] #[doc = " assert_eq!(2 * pointer_size, size_of::<*const [u8]>());"] #[doc = " assert_eq!(2 * pointer_size, size_of::<Box<[u8]>>());"] #[doc = " assert_eq!(2 * pointer_size, size_of::<Rc<[u8]>>());"] #[doc = " ```"] #[doc = ""] #[doc = " ## Trait Implementations"] #[doc = ""] #[doc = " Some traits are implemented for slices if the element type implements"] #[doc = " that trait. This includes [`Eq`], [`Hash`] and [`Ord`]."] #[doc = ""] #[doc = " ## Iteration"] #[doc = ""] #[doc = " The slices implement `IntoIterator`. The iterator yields references to the"] #[doc = " slice elements."] #[doc = ""] #[doc = " ```"] #[doc = " let numbers: &[i32] = &[0, 1, 2];"] #[doc = " for n in numbers {"] #[doc = "     println!(\"{n} is a number!\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The mutable slice yields mutable references to the elements:"] #[doc = ""] #[doc = " ```"] #[doc = " let mut scores: &mut [i32] = &mut [7, 8, 9];"] #[doc = " for score in scores {"] #[doc = "     *score += 1;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This iterator yields mutable references to the slice's elements, so while"] #[doc = " the element type of the slice is `i32`, the element type of the iterator is"] #[doc = " `&mut i32`."] #[doc = ""] #[doc = " * [`.iter`] and [`.iter_mut`] are the explicit methods to return the default"] #[doc = "   iterators."] #[doc = " * Further methods that return iterators are [`.split`], [`.splitn`],"] #[doc = "   [`.chunks`], [`.windows`] and more."] #[doc = ""] #[doc = " [`Hash`]: core::hash::Hash"] #[doc = " [`.iter`]: slice::iter"] #[doc = " [`.iter_mut`]: slice::iter_mut"] #[doc = " [`.split`]: slice::split"] #[doc = " [`.splitn`]: slice::splitn"] #[doc = " [`.chunks`]: slice::chunks"] #[doc = " [`.windows`]: slice::windows"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_slice { } #[rustc_doc_primitive = "str"] #[doc = " String slices."] #[doc = ""] #[doc = " *[See also the `std::str` module](crate::str).*"] #[doc = ""] #[doc = " The `str` type, also called a 'string slice', is the most primitive string"] #[doc = " type. It is usually seen in its borrowed form, `&str`. It is also the type"] #[doc = " of string literals, `&'static str`."] #[doc = ""] #[doc = " # Basic Usage"] #[doc = ""] #[doc = " String literals are string slices:"] #[doc = ""] #[doc = " ```"] #[doc = " let hello_world = \"Hello, World!\";"] #[doc = " ```"] #[doc = ""] #[doc = " Here we have declared a string slice initialized with a string literal."] #[doc = " String literals have a static lifetime, which means the string `hello_world`"] #[doc = " is guaranteed to be valid for the duration of the entire program."] #[doc = " We can explicitly specify `hello_world`'s lifetime as well:"] #[doc = ""] #[doc = " ```"] #[doc = " let hello_world: &'static str = \"Hello, world!\";"] #[doc = " ```"] #[doc = ""] #[doc = " # Representation"] #[doc = ""] #[doc = " A `&str` is made up of two components: a pointer to some bytes, and a"] #[doc = " length. You can look at these with the [`as_ptr`] and [`len`] methods:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::slice;"] #[doc = " use std::str;"] #[doc = ""] #[doc = " let story = \"Once upon a time...\";"] #[doc = ""] #[doc = " let ptr = story.as_ptr();"] #[doc = " let len = story.len();"] #[doc = ""] #[doc = " // story has nineteen bytes"] #[doc = " assert_eq!(19, len);"] #[doc = ""] #[doc = " // We can re-build a str out of ptr and len. This is all unsafe because"] #[doc = " // we are responsible for making sure the two components are valid:"] #[doc = " let s = unsafe {"] #[doc = "     // First, we build a &[u8]..."] #[doc = "     let slice = slice::from_raw_parts(ptr, len);"] #[doc = ""] #[doc = "     // ... and then convert that slice into a string slice"] #[doc = "     str::from_utf8(slice)"] #[doc = " };"] #[doc = ""] #[doc = " assert_eq!(s, Ok(story));"] #[doc = " ```"] #[doc = ""] #[doc = " [`as_ptr`]: str::as_ptr"] #[doc = " [`len`]: str::len"] #[doc = ""] #[doc = " Note: This example shows the internals of `&str`. `unsafe` should not be"] #[doc = " used to get a string slice under normal circumstances. Use `as_str`"] #[doc = " instead."] #[doc = ""] #[doc = " # Invariant"] #[doc = ""] #[doc = " Rust libraries may assume that string slices are always valid UTF-8."] #[doc = ""] #[doc = " Constructing a non-UTF-8 string slice is not immediate undefined behavior, but any function"] #[doc = " called on a string slice may assume that it is valid UTF-8, which means that a non-UTF-8 string"] #[doc = " slice can lead to undefined behavior down the road."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_str { } #[rustc_doc_primitive = "tuple"] #[doc (alias = "(")] #[doc (alias = ")")] #[doc (alias = "()")] #[doc = " A finite heterogeneous sequence, `(T, U, ..)`."] #[doc = ""] #[doc = " Let's cover each of those in turn:"] #[doc = ""] #[doc = " Tuples are *finite*. In other words, a tuple has a length. Here's a tuple"] #[doc = " of length `3`:"] #[doc = ""] #[doc = " ```"] #[doc = " (\"hello\", 5, 'c');"] #[doc = " ```"] #[doc = ""] #[doc = " 'Length' is also sometimes called 'arity' here; each tuple of a different"] #[doc = " length is a different, distinct type."] #[doc = ""] #[doc = " Tuples are *heterogeneous*. This means that each element of the tuple can"] #[doc = " have a different type. In that tuple above, it has the type:"] #[doc = ""] #[doc = " ```"] #[doc = " # let _:"] #[doc = " (&'static str, i32, char)"] #[doc = " # = (\"hello\", 5, 'c');"] #[doc = " ```"] #[doc = ""] #[doc = " Tuples are a *sequence*. This means that they can be accessed by position;"] #[doc = " this is called 'tuple indexing', and it looks like this:"] #[doc = ""] #[doc = " ```rust"] #[doc = " let tuple = (\"hello\", 5, 'c');"] #[doc = ""] #[doc = " assert_eq!(tuple.0, \"hello\");"] #[doc = " assert_eq!(tuple.1, 5);"] #[doc = " assert_eq!(tuple.2, 'c');"] #[doc = " ```"] #[doc = ""] #[doc = " The sequential nature of the tuple applies to its implementations of various"] #[doc = " traits. For example, in [`PartialOrd`] and [`Ord`], the elements are compared"] #[doc = " sequentially until the first non-equal set is found."] #[doc = ""] #[doc = " For more about tuples, see [the book](../book/ch03-02-data-types.html#the-tuple-type)."] #[doc = ""] #[doc = " # Trait implementations"] #[doc = ""] #[doc = " In this documentation the shorthand `(T₁, T₂, …, Tₙ)` is used to represent tuples of varying"] #[doc = " length. When that is used, any trait bound expressed on `T` applies to each element of the"] #[doc = " tuple independently. Note that this is a convenience notation to avoid repetitive"] #[doc = " documentation, not valid Rust syntax."] #[doc = ""] #[doc = " Due to a temporary restriction in Rust’s type system, the following traits are only"] #[doc = " implemented on tuples of arity 12 or less. In the future, this may change:"] #[doc = ""] #[doc = " * [`PartialEq`]"] #[doc = " * [`Eq`]"] #[doc = " * [`PartialOrd`]"] #[doc = " * [`Ord`]"] #[doc = " * [`Debug`]"] #[doc = " * [`Default`]"] #[doc = " * [`Hash`]"] #[doc = " * [`From<[T; N]>`][from]"] #[doc = ""] #[doc = " [from]: convert::From"] #[doc = " [`Debug`]: fmt::Debug"] #[doc = " [`Hash`]: hash::Hash"] #[doc = ""] #[doc = " The following traits are implemented for tuples of any length. These traits have"] #[doc = " implementations that are automatically generated by the compiler, so are not limited by"] #[doc = " missing language features."] #[doc = ""] #[doc = " * [`Clone`]"] #[doc = " * [`Copy`]"] #[doc = " * [`Send`]"] #[doc = " * [`Sync`]"] #[doc = " * [`Unpin`]"] #[doc = " * [`UnwindSafe`]"] #[doc = " * [`RefUnwindSafe`]"] #[doc = ""] #[doc = " [`UnwindSafe`]: panic::UnwindSafe"] #[doc = " [`RefUnwindSafe`]: panic::RefUnwindSafe"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let tuple = (\"hello\", 5, 'c');"] #[doc = ""] #[doc = " assert_eq!(tuple.0, \"hello\");"] #[doc = " ```"] #[doc = ""] #[doc = " Tuples are often used as a return type when you want to return more than"] #[doc = " one value:"] #[doc = ""] #[doc = " ```"] #[doc = " fn calculate_point() -> (i32, i32) {"] #[doc = "     // Don't do a calculation, that's not the point of the example"] #[doc = "     (4, 5)"] #[doc = " }"] #[doc = ""] #[doc = " let point = calculate_point();"] #[doc = ""] #[doc = " assert_eq!(point.0, 4);"] #[doc = " assert_eq!(point.1, 5);"] #[doc = ""] #[doc = " // Combining this with patterns can be nicer."] #[doc = ""] #[doc = " let (x, y) = calculate_point();"] #[doc = ""] #[doc = " assert_eq!(x, 4);"] #[doc = " assert_eq!(y, 5);"] #[doc = " ```"] #[doc = ""] #[doc = " Homogeneous tuples can be created from arrays of appropriate length:"] #[doc = ""] #[doc = " ```"] #[doc = " let array: [u32; 3] = [1, 2, 3];"] #[doc = " let tuple: (u32, u32, u32) = array.into();"] #[doc = " ```"] #[doc = ""] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_tuple { } #[doc (hidden)] impl < T > (T ,) { } #[rustc_doc_primitive = "f16"] #[doc (alias = "half")] #[doc = " A 16-bit floating-point type (specifically, the \"binary16\" type defined in IEEE 754-2008)."] #[doc = ""] #[doc = " This type is very similar to [`prim@f32`] but has decreased precision because it uses half as many"] #[doc = " bits. Please see [the documentation for `f32`](prim@f32) or [Wikipedia on half-precision"] #[doc = " values][wikipedia] for more information."] #[doc = ""] #[doc = " Note that most common platforms will not support `f16` in hardware without enabling extra target"] #[doc = " features, with the notable exception of Apple Silicon (also known as M1, M2, etc.) processors."] #[doc = " Hardware support on x86/x86-64 requires the avx512fp16 or avx10.1 features, while RISC-V requires"] #[doc = " Zfh, and Arm/AArch64 requires FEAT_FP16.  Usually the fallback implementation will be to use `f32`"] #[doc = " hardware if it exists, and convert between `f16` and `f32` when performing math."] #[doc = ""] #[doc = " *[See also the `std::f16::consts` module](crate::f16::consts).*"] #[doc = ""] #[doc = " [wikipedia]: https://en.wikipedia.org/wiki/Half-precision_floating-point_format"] #[unstable (feature = "f16" , issue = "116909")] mod prim_f16 { } #[rustc_doc_primitive = "f32"] #[doc (alias = "single")] #[doc = " A 32-bit floating-point type (specifically, the \"binary32\" type defined in IEEE 754-2008)."] #[doc = ""] #[doc = " This type can represent a wide range of decimal numbers, like `3.5`, `27`,"] #[doc = " `-113.75`, `0.0078125`, `34359738368`, `0`, `-1`. So unlike integer types"] #[doc = " (such as `i32`), floating-point types can represent non-integer numbers,"] #[doc = " too."] #[doc = ""] #[doc = " However, being able to represent this wide range of numbers comes at the"] #[doc = " cost of precision: floats can only represent some of the real numbers and"] #[doc = " calculation with floats round to a nearby representable number. For example,"] #[doc = " `5.0` and `1.0` can be exactly represented as `f32`, but `1.0 / 5.0` results"] #[doc = " in `0.20000000298023223876953125` since `0.2` cannot be exactly represented"] #[doc = " as `f32`. Note, however, that printing floats with `println` and friends will"] #[doc = " often discard insignificant digits: `println!(\"{}\", 1.0f32 / 5.0f32)` will"] #[doc = " print `0.2`."] #[doc = ""] #[doc = " Additionally, `f32` can represent some special values:"] #[doc = ""] #[doc = " - −0.0: IEEE 754 floating-point numbers have a bit that indicates their sign, so −0.0 is a"] #[doc = "   possible value. For comparison −0.0 = +0.0, but floating-point operations can carry"] #[doc = "   the sign bit through arithmetic operations. This means −0.0 × +0.0 produces −0.0 and"] #[doc = "   a negative number rounded to a value smaller than a float can represent also produces −0.0."] #[doc = " - [∞](#associatedconstant.INFINITY) and"] #[doc = "   [−∞](#associatedconstant.NEG_INFINITY): these result from calculations"] #[doc = "   like `1.0 / 0.0`."] #[doc = " - [NaN (not a number)](#associatedconstant.NAN): this value results from"] #[doc = "   calculations like `(-1.0).sqrt()`. NaN has some potentially unexpected"] #[doc = "   behavior:"] #[doc = "   - It is not equal to any float, including itself! This is the reason `f32`"] #[doc = "     doesn't implement the `Eq` trait."] #[doc = "   - It is also neither smaller nor greater than any float, making it"] #[doc = "     impossible to sort by the default comparison operation, which is the"] #[doc = "     reason `f32` doesn't implement the `Ord` trait."] #[doc = "   - It is also considered *infectious* as almost all calculations where one"] #[doc = "     of the operands is NaN will also result in NaN. The explanations on this"] #[doc = "     page only explicitly document behavior on NaN operands if this default"] #[doc = "     is deviated from."] #[doc = "   - Lastly, there are multiple bit patterns that are considered NaN."] #[doc = "     Rust does not currently guarantee that the bit patterns of NaN are"] #[doc = "     preserved over arithmetic operations, and they are not guaranteed to be"] #[doc = "     portable or even fully deterministic! This means that there may be some"] #[doc = "     surprising results upon inspecting the bit patterns,"] #[doc = "     as the same calculations might produce NaNs with different bit patterns."] #[doc = "     This also affects the sign of the NaN: checking `is_sign_positive` or `is_sign_negative` on"] #[doc = "     a NaN is the most common way to run into these surprising results."] #[doc = "     (Checking `x >= 0.0` or `x <= 0.0` avoids those surprises, but also how negative/positive"] #[doc = "     zero are treated.)"] #[doc = "     See the section below for what exactly is guaranteed about the bit pattern of a NaN."] #[doc = ""] #[doc = " When a primitive operation (addition, subtraction, multiplication, or"] #[doc = " division) is performed on this type, the result is rounded according to the"] #[doc = " roundTiesToEven direction defined in IEEE 754-2008. That means:"] #[doc = ""] #[doc = " - The result is the representable value closest to the true value, if there"] #[doc = "   is a unique closest representable value."] #[doc = " - If the true value is exactly half-way between two representable values,"] #[doc = "   the result is the one with an even least-significant binary digit."] #[doc = " - If the true value's magnitude is ≥ `f32::MAX` + 2<sup>(`f32::MAX_EXP` −"] #[doc = "   `f32::MANTISSA_DIGITS` − 1)</sup>, the result is ∞ or −∞ (preserving the"] #[doc = "   true value's sign)."] #[doc = " - If the result of a sum exactly equals zero, the outcome is +0.0 unless"] #[doc = "   both arguments were negative, then it is -0.0. Subtraction `a - b` is"] #[doc = "   regarded as a sum `a + (-b)`."] #[doc = ""] #[doc = " For more information on floating-point numbers, see [Wikipedia][wikipedia]."] #[doc = ""] #[doc = " *[See also the `std::f32::consts` module](crate::f32::consts).*"] #[doc = ""] #[doc = " [wikipedia]: https://en.wikipedia.org/wiki/Single-precision_floating-point_format"] #[doc = ""] #[doc = " # NaN bit patterns"] #[doc = ""] #[doc = " This section defines the possible NaN bit patterns returned by floating-point operations."] #[doc = ""] #[doc = " The bit pattern of a floating-point NaN value is defined by:"] #[doc = " - a sign bit."] #[doc = " - a quiet/signaling bit. Rust assumes that the quiet/signaling bit being set to `1` indicates a"] #[doc = "   quiet NaN (QNaN), and a value of `0` indicates a signaling NaN (SNaN). In the following we"] #[doc = "   will hence just call it the \"quiet bit\"."] #[doc = " - a payload, which makes up the rest of the significand (i.e., the mantissa) except for the"] #[doc = "   quiet bit."] #[doc = ""] #[doc = " The rules for NaN values differ between *arithmetic* and *non-arithmetic* (or \"bitwise\")"] #[doc = " operations. The non-arithmetic operations are unary `-`, `abs`, `copysign`, `signum`,"] #[doc = " `{to,from}_bits`, `{to,from}_{be,le,ne}_bytes` and `is_sign_{positive,negative}`. These"] #[doc = " operations are guaranteed to exactly preserve the bit pattern of their input except for possibly"] #[doc = " changing the sign bit."] #[doc = ""] #[doc = " The following rules apply when a NaN value is returned from an arithmetic operation:"] #[doc = " - The result has a non-deterministic sign."] #[doc = " - The quiet bit and payload are non-deterministically chosen from"] #[doc = "   the following set of options:"] #[doc = ""] #[doc = "   - **Preferred NaN**: The quiet bit is set and the payload is all-zero."] #[doc = "   - **Quieting NaN propagation**: The quiet bit is set and the payload is copied from any input"] #[doc = "     operand that is a NaN. If the inputs and outputs do not have the same payload size (i.e., for"] #[doc = "     `as` casts), then"] #[doc = "     - If the output is smaller than the input, low-order bits of the payload get dropped."] #[doc = "     - If the output is larger than the input, the payload gets filled up with 0s in the low-order"] #[doc = "       bits."] #[doc = "   - **Unchanged NaN propagation**: The quiet bit and payload are copied from any input operand"] #[doc = "     that is a NaN. If the inputs and outputs do not have the same size (i.e., for `as` casts), the"] #[doc = "     same rules as for \"quieting NaN propagation\" apply, with one caveat: if the output is smaller"] #[doc = "     than the input, dropping the low-order bits may result in a payload of 0; a payload of 0 is not"] #[doc = "     possible with a signaling NaN (the all-0 significand encodes an infinity) so unchanged NaN"] #[doc = "     propagation cannot occur with some inputs."] #[doc = "   - **Target-specific NaN**: The quiet bit is set and the payload is picked from a target-specific"] #[doc = "     set of \"extra\" possible NaN payloads. The set can depend on the input operand values."] #[doc = "     See the table below for the concrete NaNs this set contains on various targets."] #[doc = ""] #[doc = " In particular, if all input NaNs are quiet (or if there are no input NaNs), then the output NaN"] #[doc = " is definitely quiet. Signaling NaN outputs can only occur if they are provided as an input"] #[doc = " value. Similarly, if all input NaNs are preferred (or if there are no input NaNs) and the target"] #[doc = " does not have any \"extra\" NaN payloads, then the output NaN is guaranteed to be preferred."] #[doc = ""] #[doc = " The non-deterministic choice happens when the operation is executed; i.e., the result of a"] #[doc = " NaN-producing floating-point operation is a stable bit pattern (looking at these bits multiple"] #[doc = " times will yield consistent results), but running the same operation twice with the same inputs"] #[doc = " can produce different results."] #[doc = ""] #[doc = " These guarantees are neither stronger nor weaker than those of IEEE 754: IEEE 754 guarantees"] #[doc = " that an operation never returns a signaling NaN, whereas it is possible for operations like"] #[doc = " `SNAN * 1.0` to return a signaling NaN in Rust. Conversely, IEEE 754 makes no statement at all"] #[doc = " about which quiet NaN is returned, whereas Rust restricts the set of possible results to the"] #[doc = " ones listed above."] #[doc = ""] #[doc = " Unless noted otherwise, the same rules also apply to NaNs returned by other library functions"] #[doc = " (e.g. `min`, `minimum`, `max`, `maximum`); other aspects of their semantics and which IEEE 754"] #[doc = " operation they correspond to are documented with the respective functions."] #[doc = ""] #[doc = " When an arithmetic floating-point operation is executed in `const` context, the same rules"] #[doc = " apply: no guarantee is made about which of the NaN bit patterns described above will be"] #[doc = " returned. The result does not have to match what happens when executing the same code at"] #[doc = " runtime, and the result can vary depending on factors such as compiler version and flags."] #[doc = ""] #[doc = " ### Target-specific \"extra\" NaN values"] #[doc = ""] #[doc = " | `target_arch` | Extra payloads possible on this platform |"] #[doc = " |---------------|------------------------------------------|"] #[doc = " | `aarch64`, `arm`, `arm64ec`, `loongarch64`, `powerpc` (except when `target_abi = \"spe\"`), `powerpc64`, `riscv32`, `riscv64`, `s390x`, `x86`, `x86_64` | None |"] #[doc = " | `nvptx64` | All payloads |"] #[doc = " | `sparc`, `sparc64` | The all-one payload |"] #[doc = " | `wasm32`, `wasm64` | If all input NaNs are quiet with all-zero payload: None.<br> Otherwise: all payloads. |"] #[doc = ""] #[doc = " For targets not in this table, all payloads are possible."] #[doc = ""] #[doc = " # Algebraic operators"] #[doc = ""] #[doc = " Algebraic operators of the form `a.algebraic_*(b)` allow the compiler to optimize"] #[doc = " floating point operations using all the usual algebraic properties of real numbers --"] #[doc = " despite the fact that those properties do *not* hold on floating point numbers."] #[doc = " This can give a great performance boost since it may unlock vectorization."] #[doc = ""] #[doc = " The exact set of optimizations is unspecified but typically allows combining operations,"] #[doc = " rearranging series of operations based on mathematical properties, converting between division"] #[doc = " and reciprocal multiplication, and disregarding the sign of zero. This means that the results of"] #[doc = " elementary operations may have undefined precision, and \"non-mathematical\" values"] #[doc = " such as NaN, +/-Inf, or -0.0 may behave in unexpected ways, but these operations"] #[doc = " will never cause undefined behavior."] #[doc = ""] #[doc = " Because of the unpredictable nature of compiler optimizations, the same inputs may produce"] #[doc = " different results even within a single program run. **Unsafe code must not rely on any property"] #[doc = " of the return value for soundness.** However, implementations will generally do their best to"] #[doc = " pick a reasonable tradeoff between performance and accuracy of the result."] #[doc = ""] #[doc = " For example:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![feature(float_algebraic)]"] #[doc = " # #![allow(unused_assignments)]"] #[doc = " # let mut x: f32 = 0.0;"] #[doc = " # let a: f32 = 1.0;"] #[doc = " # let b: f32 = 2.0;"] #[doc = " # let c: f32 = 3.0;"] #[doc = " # let d: f32 = 4.0;"] #[doc = " x = a.algebraic_add(b).algebraic_add(c).algebraic_add(d);"] #[doc = " ```"] #[doc = ""] #[doc = " May be rewritten as:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(unused_assignments)]"] #[doc = " # let mut x: f32 = 0.0;"] #[doc = " # let a: f32 = 1.0;"] #[doc = " # let b: f32 = 2.0;"] #[doc = " # let c: f32 = 3.0;"] #[doc = " # let d: f32 = 4.0;"] #[doc = " x = a + b + c + d; // As written"] #[doc = " x = (a + c) + (b + d); // Reordered to shorten critical path and enable vectorization"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_f32 { } #[rustc_doc_primitive = "f64"] #[doc (alias = "double")] #[doc = " A 64-bit floating-point type (specifically, the \"binary64\" type defined in IEEE 754-2008)."] #[doc = ""] #[doc = " This type is very similar to [`prim@f32`], but has increased precision by using twice as many"] #[doc = " bits. Please see [the documentation for `f32`](prim@f32) or [Wikipedia on double-precision"] #[doc = " values][wikipedia] for more information."] #[doc = ""] #[doc = " *[See also the `std::f64::consts` module](crate::f64::consts).*"] #[doc = ""] #[doc = " [wikipedia]: https://en.wikipedia.org/wiki/Double-precision_floating-point_format"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_f64 { } #[rustc_doc_primitive = "f128"] #[doc (alias = "quad")] #[doc = " A 128-bit floating-point type (specifically, the \"binary128\" type defined in IEEE 754-2008)."] #[doc = ""] #[doc = " This type is very similar to [`prim@f32`] and [`prim@f64`], but has increased precision by using twice"] #[doc = " as many bits as `f64`. Please see [the documentation for `f32`](prim@f32) or [Wikipedia on"] #[doc = " quad-precision values][wikipedia] for more information."] #[doc = ""] #[doc = " Note that no platforms have hardware support for `f128` without enabling target specific features,"] #[doc = " as for all instruction set architectures `f128` is considered an optional feature.  Only Power ISA"] #[doc = " (\"PowerPC\") and RISC-V (via the Q extension) specify it, and only certain microarchitectures"] #[doc = " actually implement it. For x86-64 and AArch64, ISA support is not even specified, so it will always"] #[doc = " be a software implementation significantly slower than `f64`."] #[doc = ""] #[doc = " _Note: `f128` support is incomplete. Many platforms will not be able to link math functions. On"] #[doc = " x86 in particular, these functions do link but their results are always incorrect._"] #[doc = ""] #[doc = " *[See also the `std::f128::consts` module](crate::f128::consts).*"] #[doc = ""] #[doc = " [wikipedia]: https://en.wikipedia.org/wiki/Quadruple-precision_floating-point_format"] #[unstable (feature = "f128" , issue = "116909")] mod prim_f128 { } #[rustc_doc_primitive = "i8"] #[doc = " The 8-bit signed integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_i8 { } #[rustc_doc_primitive = "i16"] #[doc = " The 16-bit signed integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_i16 { } #[rustc_doc_primitive = "i32"] #[doc = " The 32-bit signed integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_i32 { } #[rustc_doc_primitive = "i64"] #[doc = " The 64-bit signed integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_i64 { } #[rustc_doc_primitive = "i128"] #[doc = " The 128-bit signed integer type."] #[doc = ""] #[doc = " # ABI compatibility"] #[doc = ""] #[doc = " Rust's `i128` is expected to be ABI-compatible with C's `__int128` on platforms where the type"] #[doc = " is available, which includes most 64-bit architectures. If any platforms that do not specify"] #[doc = " `__int128` are updated to introduce it, the Rust `i128` ABI on relevant targets will be changed"] #[doc = " to match."] #[doc = ""] #[doc = " It is important to note that in C, `__int128` is _not_ the same as `_BitInt(128)`, and the two"] #[doc = " types are allowed to have different ABIs. In particular, on x86, `__int128` and `_BitInt(128)`"] #[doc = " do not use the same alignment. `i128` is intended to always match `__int128` and does not"] #[doc = " attempt to match `_BitInt(128)` on platforms without `__int128`."] #[stable (feature = "i128" , since = "1.26.0")] mod prim_i128 { } #[rustc_doc_primitive = "u8"] #[doc = " The 8-bit unsigned integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_u8 { } #[rustc_doc_primitive = "u16"] #[doc = " The 16-bit unsigned integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_u16 { } #[rustc_doc_primitive = "u32"] #[doc = " The 32-bit unsigned integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_u32 { } #[rustc_doc_primitive = "u64"] #[doc = " The 64-bit unsigned integer type."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_u64 { } #[rustc_doc_primitive = "u128"] #[doc = " The 128-bit unsigned integer type."] #[doc = ""] #[doc = " Please see [the documentation for `i128`](prim@i128) for information on ABI compatibility."] #[stable (feature = "i128" , since = "1.26.0")] mod prim_u128 { } #[rustc_doc_primitive = "isize"] #[doc = " The pointer-sized signed integer type."] #[doc = ""] #[doc = " The size of this primitive is how many bytes it takes to reference any"] #[doc = " location in memory. For example, on a 32 bit target, this is 4 bytes"] #[doc = " and on a 64 bit target, this is 8 bytes."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_isize { } #[rustc_doc_primitive = "usize"] #[doc = " The pointer-sized unsigned integer type."] #[doc = ""] #[doc = " The size of this primitive is how many bytes it takes to reference any"] #[doc = " location in memory. For example, on a 32 bit target, this is 4 bytes"] #[doc = " and on a 64 bit target, this is 8 bytes."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_usize { } #[rustc_doc_primitive = "reference"] #[doc (alias = "&")] #[doc (alias = "&mut")] #[doc = " References, `&T` and `&mut T`."] #[doc = ""] #[doc = " A reference represents a borrow of some owned value. You can get one by using the `&` or `&mut`"] #[doc = " operators on a value, or by using a [`ref`](../std/keyword.ref.html) or"] #[doc = " <code>[ref](../std/keyword.ref.html) [mut](../std/keyword.mut.html)</code> pattern."] #[doc = ""] #[doc = " For those familiar with pointers, a reference is just a pointer that is assumed to be"] #[doc = " aligned, not null, and pointing to memory containing a valid value of `T` - for example,"] #[doc = " <code>&[bool]</code> can only point to an allocation containing the integer values `1`"] #[doc = " ([`true`](../std/keyword.true.html)) or `0` ([`false`](../std/keyword.false.html)), but"] #[doc = " creating a <code>&[bool]</code> that points to an allocation containing"] #[doc = " the value `3` causes undefined behavior."] #[doc = " In fact, <code>[Option]\\<&T></code> has the same memory representation as a"] #[doc = " nullable but aligned pointer, and can be passed across FFI boundaries as such."] #[doc = ""] #[doc = " In most cases, references can be used much like the original value. Field access, method"] #[doc = " calling, and indexing work the same (save for mutability rules, of course). In addition, the"] #[doc = " comparison operators transparently defer to the referent's implementation, allowing references"] #[doc = " to be compared the same as owned values."] #[doc = ""] #[doc = " References have a lifetime attached to them, which represents the scope for which the borrow is"] #[doc = " valid. A lifetime is said to \"outlive\" another one if its representative scope is as long or"] #[doc = " longer than the other. The `'static` lifetime is the longest lifetime, which represents the"] #[doc = " total life of the program. For example, string literals have a `'static` lifetime because the"] #[doc = " text data is embedded into the binary of the program, rather than in an allocation that needs"] #[doc = " to be dynamically managed."] #[doc = ""] #[doc = " `&mut T` references can be freely coerced into `&T` references with the same referent type, and"] #[doc = " references with longer lifetimes can be freely coerced into references with shorter ones."] #[doc = ""] #[doc = " Reference equality by address, instead of comparing the values pointed to, is accomplished via"] #[doc = " implicit reference-pointer coercion and raw pointer equality via [`ptr::eq`], while"] #[doc = " [`PartialEq`] compares values."] #[doc = ""] #[doc = " ```"] #[doc = " use std::ptr;"] #[doc = ""] #[doc = " let five = 5;"] #[doc = " let other_five = 5;"] #[doc = " let five_ref = &five;"] #[doc = " let same_five_ref = &five;"] #[doc = " let other_five_ref = &other_five;"] #[doc = ""] #[doc = " assert!(five_ref == same_five_ref);"] #[doc = " assert!(five_ref == other_five_ref);"] #[doc = ""] #[doc = " assert!(ptr::eq(five_ref, same_five_ref));"] #[doc = " assert!(!ptr::eq(five_ref, other_five_ref));"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on how to use references, see [the book's section on \"References and"] #[doc = " Borrowing\"][book-refs]."] #[doc = ""] #[doc = " [book-refs]: ../book/ch04-02-references-and-borrowing.html"] #[doc = ""] #[doc = " # Trait implementations"] #[doc = ""] #[doc = " The following traits are implemented for all `&T`, regardless of the type of its referent:"] #[doc = ""] #[doc = " * [`Copy`]"] #[doc = " * [`Clone`] \\(Note that this will not defer to `T`'s `Clone` implementation if it exists!)"] #[doc = " * [`Deref`]"] #[doc = " * [`Borrow`]"] #[doc = " * [`fmt::Pointer`]"] #[doc = ""] #[doc = " [`Deref`]: ops::Deref"] #[doc = " [`Borrow`]: borrow::Borrow"] #[doc = ""] #[doc = " `&mut T` references get all of the above except `Copy` and `Clone` (to prevent creating"] #[doc = " multiple simultaneous mutable borrows), plus the following, regardless of the type of its"] #[doc = " referent:"] #[doc = ""] #[doc = " * [`DerefMut`]"] #[doc = " * [`BorrowMut`]"] #[doc = ""] #[doc = " [`DerefMut`]: ops::DerefMut"] #[doc = " [`BorrowMut`]: borrow::BorrowMut"] #[doc = " [bool]: prim@bool"] #[doc = ""] #[doc = " The following traits are implemented on `&T` references if the underlying `T` also implements"] #[doc = " that trait:"] #[doc = ""] #[doc = " * All the traits in [`std::fmt`] except [`fmt::Pointer`] (which is implemented regardless of the type of its referent) and [`fmt::Write`]"] #[doc = " * [`PartialOrd`]"] #[doc = " * [`Ord`]"] #[doc = " * [`PartialEq`]"] #[doc = " * [`Eq`]"] #[doc = " * [`AsRef`]"] #[doc = " * [`Fn`] \\(in addition, `&T` references get [`FnMut`] and [`FnOnce`] if `T: Fn`)"] #[doc = " * [`Hash`]"] #[doc = " * [`ToSocketAddrs`]"] #[doc = " * [`Sync`]"] #[doc = ""] #[doc = " [`std::fmt`]: fmt"] #[doc = " [`Hash`]: hash::Hash"] #[doc = " [`ToSocketAddrs`]: ../std/net/trait.ToSocketAddrs.html"] #[doc = ""] #[doc = " `&mut T` references get all of the above except `ToSocketAddrs`, plus the following, if `T`"] #[doc = " implements that trait:"] #[doc = ""] #[doc = " * [`AsMut`]"] #[doc = " * [`FnMut`] \\(in addition, `&mut T` references get [`FnOnce`] if `T: FnMut`)"] #[doc = " * [`fmt::Write`]"] #[doc = " * [`Iterator`]"] #[doc = " * [`DoubleEndedIterator`]"] #[doc = " * [`ExactSizeIterator`]"] #[doc = " * [`FusedIterator`]"] #[doc = " * [`TrustedLen`]"] #[doc = " * [`Send`]"] #[doc = " * [`io::Write`]"] #[doc = " * [`Read`]"] #[doc = " * [`Seek`]"] #[doc = " * [`BufRead`]"] #[doc = ""] #[doc = " [`FusedIterator`]: iter::FusedIterator"] #[doc = " [`TrustedLen`]: iter::TrustedLen"] #[doc = " [`Seek`]: ../std/io/trait.Seek.html"] #[doc = " [`BufRead`]: ../std/io/trait.BufRead.html"] #[doc = " [`Read`]: ../std/io/trait.Read.html"] #[doc = " [`io::Write`]: ../std/io/trait.Write.html"] #[doc = ""] #[doc = " In addition, `&T` references implement [`Send`] if and only if `T` implements [`Sync`]."] #[doc = ""] #[doc = " Note that due to method call deref coercion, simply calling a trait method will act like they"] #[doc = " work on references as well as they do on owned values! The implementations described here are"] #[doc = " meant for generic contexts, where the final type `T` is a type parameter or otherwise not"] #[doc = " locally known."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " For all types, `T: ?Sized`, and for all `t: &T` or `t: &mut T`, when such values cross an API"] #[doc = " boundary, the following invariants must generally be upheld:"] #[doc = ""] #[doc = " * `t` is non-null"] #[doc = " * `t` is aligned to `align_of_val(t)`"] #[doc = " * if `size_of_val(t) > 0`, then `t` is dereferenceable for `size_of_val(t)` many bytes"] #[doc = ""] #[doc = " If `t` points at address `a`, being \"dereferenceable\" for N bytes means that the memory range"] #[doc = " `[a, a + N)` is all contained within a single [allocation]."] #[doc = ""] #[doc = " For instance, this means that unsafe code in a safe function may assume these invariants are"] #[doc = " ensured of arguments passed by the caller, and it may assume that these invariants are ensured"] #[doc = " of return values from any safe functions it calls."] #[doc = ""] #[doc = " For the other direction, things are more complicated: when unsafe code passes arguments"] #[doc = " to safe functions or returns values from safe functions, they generally must *at least*"] #[doc = " not violate these invariants. The full requirements are stronger, as the reference generally"] #[doc = " must point to data that is safe to use at type `T`."] #[doc = ""] #[doc = " It is not decided yet whether unsafe code may violate these invariants temporarily on internal"] #[doc = " data. As a consequence, unsafe code which violates these invariants temporarily on internal data"] #[doc = " may be unsound or become unsound in future versions of Rust depending on how this question is"] #[doc = " decided."] #[doc = ""] #[doc = " [allocation]: ptr#allocation"] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_ref { } #[rustc_doc_primitive = "fn"] #[doc = " Function pointers, like `fn(usize) -> bool`."] #[doc = ""] #[doc = " *See also the traits [`Fn`], [`FnMut`], and [`FnOnce`].*"] #[doc = ""] #[doc = " Function pointers are pointers that point to *code*, not data. They can be called"] #[doc = " just like functions. Like references, function pointers are, among other things, assumed to"] #[doc = " not be null, so if you want to pass a function pointer over FFI and be able to accommodate null"] #[doc = " pointers, make your type [`Option<fn()>`](core::option#options-and-pointers-nullable-pointers)"] #[doc = " with your required signature."] #[doc = ""] #[doc = " Note that FFI requires additional care to ensure that the ABI for both sides of the call match."] #[doc = " The exact requirements are not currently documented."] #[doc = ""] #[doc = " ### Safety"] #[doc = ""] #[doc = " Plain function pointers are obtained by casting either plain functions, or closures that don't"] #[doc = " capture an environment:"] #[doc = ""] #[doc = " ```"] #[doc = " fn add_one(x: usize) -> usize {"] #[doc = "     x + 1"] #[doc = " }"] #[doc = ""] #[doc = " let ptr: fn(usize) -> usize = add_one;"] #[doc = " assert_eq!(ptr(5), 6);"] #[doc = ""] #[doc = " let clos: fn(usize) -> usize = |x| x + 5;"] #[doc = " assert_eq!(clos(5), 10);"] #[doc = " ```"] #[doc = ""] #[doc = " In addition to varying based on their signature, function pointers come in two flavors: safe"] #[doc = " and unsafe. Plain `fn()` function pointers can only point to safe functions,"] #[doc = " while `unsafe fn()` function pointers can point to safe or unsafe functions."] #[doc = ""] #[doc = " ```"] #[doc = " fn add_one(x: usize) -> usize {"] #[doc = "     x + 1"] #[doc = " }"] #[doc = ""] #[doc = " unsafe fn add_one_unsafely(x: usize) -> usize {"] #[doc = "     x + 1"] #[doc = " }"] #[doc = ""] #[doc = " let safe_ptr: fn(usize) -> usize = add_one;"] #[doc = ""] #[doc = " //ERROR: mismatched types: expected normal fn, found unsafe fn"] #[doc = " //let bad_ptr: fn(usize) -> usize = add_one_unsafely;"] #[doc = ""] #[doc = " let unsafe_ptr: unsafe fn(usize) -> usize = add_one_unsafely;"] #[doc = " let really_safe_ptr: unsafe fn(usize) -> usize = add_one;"] #[doc = " ```"] #[doc = ""] #[doc = " ### ABI"] #[doc = ""] #[doc = " On top of that, function pointers can vary based on what ABI they use. This"] #[doc = " is achieved by adding the `extern` keyword before the type, followed by the"] #[doc = " ABI in question. The default ABI is \"Rust\", i.e., `fn()` is the exact same"] #[doc = " type as `extern \"Rust\" fn()`. A pointer to a function with C ABI would have"] #[doc = " type `extern \"C\" fn()`."] #[doc = ""] #[doc = " `extern \"ABI\" { ... }` blocks declare functions with ABI \"ABI\". The default"] #[doc = " here is \"C\", i.e., functions declared in an `extern {...}` block have \"C\""] #[doc = " ABI."] #[doc = ""] #[doc = " For more information and a list of supported ABIs, see [the nomicon's"] #[doc = " section on foreign calling conventions][nomicon-abi]."] #[doc = ""] #[doc = " [nomicon-abi]: ../nomicon/ffi.html#foreign-calling-conventions"] #[doc = ""] #[doc = " ### Variadic functions"] #[doc = ""] #[doc = " Extern function declarations with the \"C\" or \"cdecl\" ABIs can also be *variadic*, allowing them"] #[doc = " to be called with a variable number of arguments. Normal Rust functions, even those with an"] #[doc = " `extern \"ABI\"`, cannot be variadic. For more information, see [the nomicon's section on"] #[doc = " variadic functions][nomicon-variadic]."] #[doc = ""] #[doc = " [nomicon-variadic]: ../nomicon/ffi.html#variadic-functions"] #[doc = ""] #[doc = " ### Creating function pointers"] #[doc = ""] #[doc = " When `bar` is the name of a function, then the expression `bar` is *not* a"] #[doc = " function pointer. Rather, it denotes a value of an unnameable type that"] #[doc = " uniquely identifies the function `bar`. The value is zero-sized because the"] #[doc = " type already identifies the function. This has the advantage that \"calling\""] #[doc = " the value (it implements the `Fn*` traits) does not require dynamic"] #[doc = " dispatch."] #[doc = ""] #[doc = " This zero-sized type *coerces* to a regular function pointer. For example:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn bar(x: i32) {}"] #[doc = ""] #[doc = " let not_bar_ptr = bar; // `not_bar_ptr` is zero-sized, uniquely identifying `bar`"] #[doc = " assert_eq!(size_of_val(&not_bar_ptr), 0);"] #[doc = ""] #[doc = " let bar_ptr: fn(i32) = not_bar_ptr; // force coercion to function pointer"] #[doc = " assert_eq!(size_of_val(&bar_ptr), size_of::<usize>());"] #[doc = ""] #[doc = " let footgun = &bar; // this is a shared reference to the zero-sized type identifying `bar`"] #[doc = " ```"] #[doc = ""] #[doc = " The last line shows that `&bar` is not a function pointer either. Rather, it"] #[doc = " is a reference to the function-specific ZST. `&bar` is basically never what you"] #[doc = " want when `bar` is a function."] #[doc = ""] #[doc = " ### Casting to and from integers"] #[doc = ""] #[doc = " You can cast function pointers directly to integers:"] #[doc = ""] #[doc = " ```rust"] #[doc = " let fnptr: fn(i32) -> i32 = |x| x+2;"] #[doc = " let fnptr_addr = fnptr as usize;"] #[doc = " ```"] #[doc = ""] #[doc = " However, a direct cast back is not possible. You need to use `transmute`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #[cfg(not(miri))] { // FIXME: use strict provenance APIs once they are stable, then remove this `cfg`"] #[doc = " # let fnptr: fn(i32) -> i32 = |x| x+2;"] #[doc = " # let fnptr_addr = fnptr as usize;"] #[doc = " let fnptr = fnptr_addr as *const ();"] #[doc = " let fnptr: fn(i32) -> i32 = unsafe { std::mem::transmute(fnptr) };"] #[doc = " assert_eq!(fnptr(40), 42);"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " Crucially, we `as`-cast to a raw pointer before `transmute`ing to a function pointer."] #[doc = " This avoids an integer-to-pointer `transmute`, which can be problematic."] #[doc = " Transmuting between raw pointers and function pointers (i.e., two pointer types) is fine."] #[doc = ""] #[doc = " Note that all of this is not portable to platforms where function pointers and data pointers"] #[doc = " have different sizes."] #[doc = ""] #[doc = " ### ABI compatibility"] #[doc = ""] #[doc = " Generally, when a function is declared with one signature and called via a function pointer with"] #[doc = " a different signature, the two signatures must be *ABI-compatible* or else calling the function"] #[doc = " via that function pointer is Undefined Behavior. ABI compatibility is a lot stricter than merely"] #[doc = " having the same memory layout; for example, even if `i32` and `f32` have the same size and"] #[doc = " alignment, they might be passed in different registers and hence not be ABI-compatible."] #[doc = ""] #[doc = " ABI compatibility as a concern only arises in code that alters the type of function pointers,"] #[doc = " and code that imports functions via `extern` blocks. Altering the type of function pointers is"] #[doc = " wildly unsafe (as in, a lot more unsafe than even [`transmute_copy`][mem::transmute_copy]), and"] #[doc = " should only occur in the most exceptional circumstances. Most Rust code just imports functions"] #[doc = " via `use`. So, most likely you do not have to worry about ABI compatibility."] #[doc = ""] #[doc = " But assuming such circumstances, what are the rules? For this section, we are only considering"] #[doc = " the ABI of direct Rust-to-Rust calls (with both definition and callsite visible to the"] #[doc = " Rust compiler), not linking in general -- once functions are imported via `extern` blocks, there"] #[doc = " are more things to consider that we do not go into here. Note that this also applies to"] #[doc = " passing/calling functions across language boundaries via function pointers."] #[doc = ""] #[doc = " **Nothing in this section should be taken as a guarantee for non-Rust-to-Rust calls, even with"] #[doc = " types from `core::ffi` or `libc`**."] #[doc = ""] #[doc = " For two signatures to be considered *ABI-compatible*, they must use a compatible ABI string,"] #[doc = " must take the same number of arguments, and the individual argument types and the return types"] #[doc = " must be ABI-compatible. The ABI string is declared via `extern \"ABI\" fn(...) -> ...`; note that"] #[doc = " `fn name(...) -> ...` implicitly uses the `\"Rust\"` ABI string and `extern fn name(...) -> ...`"] #[doc = " implicitly uses the `\"C\"` ABI string."] #[doc = ""] #[doc = " The ABI strings are guaranteed to be compatible if they are the same, or if the caller ABI"] #[doc = " string is `$X-unwind` and the callee ABI string is `$X`, where `$X` is one of the following:"] #[doc = " \"C\", \"aapcs\", \"fastcall\", \"stdcall\", \"system\", \"sysv64\", \"thiscall\", \"vectorcall\", \"win64\"."] #[doc = ""] #[doc = " The following types are guaranteed to be ABI-compatible:"] #[doc = ""] #[doc = " - `*const T`, `*mut T`, `&T`, `&mut T`, `Box<T>` (specifically, only `Box<T, Global>`), and"] #[doc = "   `NonNull<T>` are all ABI-compatible with each other for all `T`. They are also ABI-compatible"] #[doc = "   with each other for _different_ `T` if they have the same metadata type (`<T as"] #[doc = "   Pointee>::Metadata`)."] #[doc = " - `usize` is ABI-compatible with the `uN` integer type of the same size, and likewise `isize` is"] #[doc = "   ABI-compatible with the `iN` integer type of the same size."] #[doc = " - `char` is ABI-compatible with `u32`."] #[doc = " - Any two `fn` (function pointer) types are ABI-compatible with each other if they have the same"] #[doc = "   ABI string or the ABI string only differs in a trailing `-unwind`, independent of the rest of"] #[doc = "   their signature. (This means you can pass `fn()` to a function expecting `fn(i32)`, and the"] #[doc = "   call will be valid ABI-wise. The callee receives the result of transmuting the function pointer"] #[doc = "   from `fn()` to `fn(i32)`; that transmutation is itself a well-defined operation, it's just"] #[doc = "   almost certainly UB to later call that function pointer.)"] #[doc = " - Any two types with size 0 and alignment 1 are ABI-compatible."] #[doc = " - A `repr(transparent)` type `T` is ABI-compatible with its unique non-trivial field, i.e., the"] #[doc = "   unique field that doesn't have size 0 and alignment 1 (if there is such a field)."] #[doc = " - `i32` is ABI-compatible with `NonZero<i32>`, and similar for all other integer types."] #[doc = " - If `T` is guaranteed to be subject to the [null pointer"] #[doc = "   optimization](option/index.html#representation), and `E` is an enum satisfying the following"] #[doc = "   requirements, then `T` and `E` are ABI-compatible. Such an enum `E` is called \"option-like\"."] #[doc = "   - The enum `E` uses the [`Rust` representation], and is not modified by the `align` or"] #[doc = "     `packed` representation modifiers."] #[doc = "   - The enum `E` has exactly two variants."] #[doc = "   - One variant has exactly one field, of type `T`."] #[doc = "   - All fields of the other variant are zero-sized with 1-byte alignment."] #[doc = ""] #[doc = " Furthermore, ABI compatibility satisfies the following general properties:"] #[doc = ""] #[doc = " - Every type is ABI-compatible with itself."] #[doc = " - If `T1` and `T2` are ABI-compatible and `T2` and `T3` are ABI-compatible, then so are `T1` and"] #[doc = "   `T3` (i.e., ABI-compatibility is transitive)."] #[doc = " - If `T1` and `T2` are ABI-compatible, then so are `T2` and `T1` (i.e., ABI-compatibility is"] #[doc = "   symmetric)."] #[doc = ""] #[doc = " More signatures can be ABI-compatible on specific targets, but that should not be relied upon"] #[doc = " since it is not portable and not a stable guarantee."] #[doc = ""] #[doc = " Noteworthy cases of types *not* being ABI-compatible in general are:"] #[doc = " * `bool` vs `u8`, `i32` vs `u32`, `char` vs `i32`: on some targets, the calling conventions for"] #[doc = "   these types differ in terms of what they guarantee for the remaining bits in the register that"] #[doc = "   are not used by the value."] #[doc = " * `i32` vs `f32` are not compatible either, as has already been mentioned above."] #[doc = " * `struct Foo(u32)` and `u32` are not compatible (without `repr(transparent)`) since structs are"] #[doc = "   aggregate types and often passed in a different way than primitives like `i32`."] #[doc = ""] #[doc = " Note that these rules describe when two completely known types are ABI-compatible. When"] #[doc = " considering ABI compatibility of a type declared in another crate (including the standard"] #[doc = " library), consider that any type that has a private field or the `#[non_exhaustive]` attribute"] #[doc = " may change its layout as a non-breaking update unless documented otherwise -- so for instance,"] #[doc = " even if such a type is a 1-ZST or `repr(transparent)` right now, this might change with any"] #[doc = " library version bump."] #[doc = ""] #[doc = " If the declared signature and the signature of the function pointer are ABI-compatible, then the"] #[doc = " function call behaves as if every argument was [`transmute`d][mem::transmute] from the"] #[doc = " type in the function pointer to the type at the function declaration, and the return value is"] #[doc = " [`transmute`d][mem::transmute] from the type in the declaration to the type in the"] #[doc = " pointer. All the usual caveats and concerns around transmutation apply; for instance, if the"] #[doc = " function expects a `NonZero<i32>` and the function pointer uses the ABI-compatible type"] #[doc = " `Option<NonZero<i32>>`, and the value used for the argument is `None`, then this call is Undefined"] #[doc = " Behavior since transmuting `None::<NonZero<i32>>` to `NonZero<i32>` violates the non-zero"] #[doc = " requirement."] #[doc = ""] #[doc = " ### Trait implementations"] #[doc = ""] #[doc = " In this documentation the shorthand `fn(T₁, T₂, …, Tₙ)` is used to represent non-variadic"] #[doc = " function pointers of varying length. Note that this is a convenience notation to avoid"] #[doc = " repetitive documentation, not valid Rust syntax."] #[doc = ""] #[doc = " The following traits are implemented for function pointers with any number of arguments and"] #[doc = " any ABI."] #[doc = ""] #[doc = " * [`PartialEq`]"] #[doc = " * [`Eq`]"] #[doc = " * [`PartialOrd`]"] #[doc = " * [`Ord`]"] #[doc = " * [`Hash`]"] #[doc = " * [`Pointer`]"] #[doc = " * [`Debug`]"] #[doc = " * [`Clone`]"] #[doc = " * [`Copy`]"] #[doc = " * [`Send`]"] #[doc = " * [`Sync`]"] #[doc = " * [`Unpin`]"] #[doc = " * [`UnwindSafe`]"] #[doc = " * [`RefUnwindSafe`]"] #[doc = ""] #[doc = " Note that while this type implements `PartialEq`, comparing function pointers is unreliable:"] #[doc = " pointers to the same function can compare inequal (because functions are duplicated in multiple"] #[doc = " codegen units), and pointers to *different* functions can compare equal (since identical"] #[doc = " functions can be deduplicated within a codegen unit)."] #[doc = ""] #[doc = " [`Hash`]: hash::Hash"] #[doc = " [`Pointer`]: fmt::Pointer"] #[doc = " [`UnwindSafe`]: panic::UnwindSafe"] #[doc = " [`RefUnwindSafe`]: panic::RefUnwindSafe"] #[doc = " [`Rust` representation]: <https://doc.rust-lang.org/reference/type-layout.html#the-rust-representation>"] #[doc = ""] #[doc = " In addition, all *safe* function pointers implement [`Fn`], [`FnMut`], and [`FnOnce`], because"] #[doc = " these traits are specially known to the compiler."] #[stable (feature = "rust1" , since = "1.0.0")] mod prim_fn { } #[doc (hidden)] impl < Ret , T > fn (T) -> Ret { }